import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';import {spawnSync} from 'node:child_process';import {performance} from 'node:perf_hooks';
const rt=path.join(process.env.LOCALAPPDATA,'SigTradingCup/paper-runtime'),original=path.join(rt,'journal.jsonl'),work=path.join(rt,'offline-benchmarks','journal-stream-v2-'+Date.now());
fs.mkdirSync(work,{recursive:true,mode:0o700});const before=fs.statSync(original,{bigint:true}),wanted=Number(before.size);if(!Number.isSafeInteger(wanted))throw Error('FRONTIER');
const disk=fs.statfsSync(rt);if(disk.bavail*disk.bsize<wanted*1.3)throw Error('DISK_HEADROOM');
const input=fs.openSync(original,'r'),sealed=path.join(work,'sealed-original-prefix.jsonl'),output=fs.openSync(sealed,'wx',0o600),buf=Buffer.allocUnsafe(1024*1024);let total=0,lastNewline=0;const copyStart=performance.now();try{while(total<wanted){const n=fs.readSync(input,buf,0,Math.min(buf.length,wanted-total),total);if(!n)throw Error('SOURCE_TRUNCATED');fs.writeSync(output,buf,0,n);const i=buf.subarray(0,n).lastIndexOf(10);if(i>=0)lastNewline=total+i+1;total+=n;}fs.ftruncateSync(output,lastNewline);fs.fsyncSync(output);}finally{fs.closeSync(input);fs.closeSync(output)}const copyMs=performance.now()-copyStart;
const exeV2=path.resolve('backend-rust/journal-stream-v2/target/release/baal-journal-stream-v2.exe'),binding=JSON.parse(fs.readFileSync(path.join(rt,'collector-native-journal.json'))),b=binding.nativeBackend||binding.binding||binding;const exeV1=path.join(rt,'journal-native-builds',b.binaryHash,'baal-journal-restore.exe');if(!fs.existsSync(exeV1))throw Error('PINNED_NATIVE_MISSING');
const hashFile=file=>{const h=createHash('sha256'),fd=fs.openSync(file,'r'),tmp=Buffer.allocUnsafe(1024*1024);try{let n;while((n=fs.readSync(fd,tmp,0,tmp.length,null)))h.update(tmp.subarray(0,n));}finally{fs.closeSync(fd)}return h.digest('hex')};
const finalV2BinaryHash=hashFile(exeV2);const hashStart=performance.now(),expectedSha=hashFile(sealed),prefixHashMs=performance.now()-hashStart;
function invoke(exe,expected,name){const out=path.join(work,name+'.json'),t=performance.now(),r=spawnSync(exe,['--journal',sealed,'--end-byte',String(lastNewline),'--expected-sha',expected,'--out',out],{encoding:'utf8',windowsHide:true,maxBuffer:2048});if(r.status!==0)throw Error(r.stderr.trim()||'NATIVE_FAILED');return{result:JSON.parse(fs.readFileSync(out)),wallMs:performance.now()-t}}
const old=invoke(exeV1,expectedSha,'v1'),next=invoke(exeV2,'COMPUTE','v2');const stateHash=x=>createHash('sha256').update(JSON.stringify(x.lastBody)).digest('hex');
if(next.result.sourceHash!==expectedSha||next.result.records!==old.result.records||next.result.tailHash!==old.result.tailHash||stateHash(next.result)!==stateHash(old.result))throw Error('PARITY');
const evidence={schemaVersion:1,at:new Date().toISOString(),mode:'sealed_actual_original_journal_onepass_v2',sourceBytes:lastNewline,sourceHash:expectedSha,records:next.result.records,tailHash:next.result.tailHash,lastBodyHash:stateHash(next.result),copyMs,prefixHashMs,v1NativeMs:old.wallMs,v1TotalMs:prefixHashMs+old.wallMs,v2OnePassMs:next.wallMs,speedup:(prefixHashMs+old.wallMs)/next.wallMs,v1InternalMs:old.result.verifyMs,v2InternalMs:next.result.verifyMs,v2EngineHash:next.result.engineHash,v2BinaryHash:finalV2BinaryHash,sourceStamp:next.result.sourceStamp,chainParity:true,stateParity:true,readOnly:true,networkRequests:0,competitionOrders:0,profitabilityEstablished:false,sourceChangingDuringCopyPossible:true,canonicalSnapshotValidationPassed:true};
if(hashFile(exeV2)!==finalV2BinaryHash)throw Error('BINARY_CHANGED');fs.writeFileSync('data/journal-stream-v2-benchmark-20261005.json',JSON.stringify(evidence,null,2)+'\n');
const resolved=path.resolve(sealed),owned=path.resolve(work);if(path.dirname(resolved)!==owned||!owned.startsWith(path.resolve(rt,'offline-benchmarks')+path.sep))throw Error('DELETE_SCOPE');fs.unlinkSync(resolved);evidence.temporarySnapshotDeleted=true;fs.writeFileSync('data/journal-stream-v2-benchmark-20261005.json',JSON.stringify(evidence,null,2)+'\n');console.log(JSON.stringify(evidence));
